from mk import *
from lib import fbd
STRICT["on"] = True
import math

def fig():
    g = Fig(560, 300, "מסילה חסרת חיכוך: רבע מעגל AB ברדיוס R סביב O, ואחריו לולאה מעגלית BCDEF ברדיוס r סביב O'. EC הוא קוטר אופקי של הלולאה")
    O = (250, 40); R = 210
    g.path(f"M {O[0] - R},{O[1]} A {R} {R} 0 0 0 {O[0]},{O[1] + R}", width=3)
    g.dot(*O); g.text(O[0] + 10, O[1] + 4, "O", anchor="start")
    g.ball(O[0] - R + 6, O[1] - 6, 6); g.text(O[0] - R - 6, O[1] - 12, "A", anchor="end")
    B = (O[0], O[1] + R); r = 56; Oc = (B[0], B[1] - r)
    g.circle(*Oc, r, fill="none", stroke="var(--d-line)", width=3)
    g.path(f"M {B[0]},{B[1]} A {R} {R} 0 0 0 {O[0] + R},{O[1]}", width=3)  # the track rises again on the right (U shape)
    g.dot(*Oc); g.text(Oc[0] + 8, Oc[1] + 4, "O'", anchor="start")
    for (x, y, t, dx, dy) in ((B[0], B[1], "B", 0, 20), (Oc[0] + r, Oc[1], "C", 14, 5), (Oc[0], Oc[1] - r, "D", 0, -8), (Oc[0] - r, Oc[1], "E", -14, 5)):
        g.dot(x, y); g.text(x + dx, y + dy, t)
    Fp = (O[0] + R * math.cos(math.radians(-35)), O[1] - R * math.sin(math.radians(-35))); g.dot(*Fp); g.text(Fp[0] + 12, Fp[1] + 4, "F", anchor="start")
    g.dim(O[0] - R - 20, O[1], O[0] - R - 20, B[1], "R")
    return g

E(id="bagrut-1993-q4", year=1993, label="1993 שאלה 4", topic="circular", sub="circ-vertical", diff=4, fig=fig,
  stem=r"בתרשים מתוארת מסילה בלי חיכוך, $ABCDEF$. הקטע $AB$ הוא רבע מעגל שרדיוסו $R$ ומרכזו $O$. הקטע $BCDE$ הוא מעגל שרדיוסו $r$ ומרכזו $O'$. הנקודות $O$ ו-$O'$ על אותו קו אנכי. משחררים גוף קטן ממנוחה בנקודה $A$, והוא נע לאורך המסילה. $EC$ הוא קוטר אופקי של המעגל שמרכזו $O'$. ענו בעזרת נתוני השאלה.",
  parts=[
    P("א", r"מה גודל המהירות של הגוף בנקודה $C$, ומה הכיוון שלה?", choice([r"$\sqrt{2g(R - r)}$, כלפי מעלה", r"$\sqrt{2gR}$, כלפי מעלה", r"$\sqrt{2g(R - r)}$, אופקית אל $O'$", r"$\sqrt{2g(R - 2r)}$, כלפי מעלה"], 0), ["principle"], [
        X(r"אין חיכוך, והכוח הנורמלי ניצב לתנועה ולא עושה עבודה. לכן האנרגיה המכנית נשמרת. רמת הייחוס לגובה היא הנקודה B, התחתונה."),
        S(r"הפרש הגבהים", r"הנקודה A גבוהה מ-B ברדיוס הגדול, והנקודה C גבוהה מ-B ברדיוס הקטן", r"\Delta h = R - r"),
        S(r"שימור אנרגיה", r"בנקודה A הגוף במנוחה", r"mgR + 0 = mgr + \tfrac{1}{2}m v_C^2", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
        S(r"מחלקים במסה ומבודדים", r"המסה מצטמצמת", r"v_C = \sqrt{2g(R - r)}"),
        S(r"הכיוון", r"המהירות משיקה למעגל. בנקודה C, בקצה הקוטר האופקי, המשיק אנכי, והגוף עולה", r"\vec v_C\ \uparrow"),
    ], r"$v_C = \sqrt{2g(R - r)}$, כלפי מעלה (משיק למעגל)", key=r"√(2g(R−r)) כלפי מעלה"),
    P("ב1", r"מה התאוצה הרדיאלית בנקודה $C$?", choice([r"$2g\left(\frac{R}{r} - 1\right)$, אופקית אל $O'$", r"$g\left(\frac{R}{r} - 1\right)$, אופקית אל $O'$", r"$2g\left(\frac{R}{r} - 1\right)$, כלפי מטה", r"$\frac{2gR}{r}$, אופקית אל $O'$"], 0), ["principle", "algebra"], [
        S(r"התאוצה הרדיאלית", r"מציבים את ריבוע המהירות מסעיף א. היא מכוונת אל מרכז המעגל, אופקית", r"a_R = \frac{v_C^2}{r} = \frac{2g(R - r)}{r} = 2g\left(\frac{R}{r} - 1\right)", eq=r"a_R = \frac{v^2}{r}"),
    ], r"$a_R = 2g\left(\frac{R}{r} - 1\right)$, אופקית אל $O'$", key=r"2g(R/r −1)"),
    P("ב2", r"מה התאוצה המשיקית בנקודה $C$?", choice([r"$g$, כלפי מטה", r"אפס", r"$g$, כלפי מעלה", r"$2g$, כלפי מטה"], 0), ["fbd", "principle"], [
        D(r"תרשים הכוחות על הגוף בנקודה C", lambda: fbd([("N", 180, 1.0), ("mg", -90, 0.9)],
            "תרשים כוחות על הגוף בנקודה C: הכוח הנורמלי של המסילה אופקי, אל מרכז המעגל, וכוח הכובד כלפי מטה. בכיוון המשיק, האנכי, פועל רק הכובד",
            positive=-90, body="ball", note="המרכז משמאל")),
        S(r"משוואת כוחות בכיוון המשיק", r"בנקודה הזו המשיק אנכי. בכיוון הזה פועל רק הכובד, והכוח הנורמלי ניצב לו. בוחרים כלפי מטה כחיובי", r"mg = m\,a_t \;\Rightarrow\; a_t = g", eq=r"\Sigma\vec F = m\vec a"),
    ], r"$a_t = g$, כלפי מטה", key=r"g"),
    P("ג", r"מה צריך להיות היחס הקטן ביותר $R/r$, כדי שהגוף לא ייפרד מהמסילה המעגלית שמרכזה $O'$?", num(2.5, ""), ["fbd", "principle", "algebra"], [
        X(r"הנקודה המסוכנת היא ראש הלולאה, D. שם המרכז מתחת לגוף, ובוחרים כלפי מטה כחיובי."),
        D(r"תרשים הכוחות על הגוף בראש הלולאה", lambda: fbd([("N", -90, 0.6, -12), ("mg", -90, 0.9, 12)],
            "תרשים כוחות על הגוף בראש הלולאה: הכוח הנורמלי של המסילה וכוח הכובד, שניהם כלפי מטה, אל המרכז. הכיוון החיובי כלפי מטה",
            positive=-90, body="ball", note="המרכז מתחת")),
        S(r"משוואת כוחות בכיוון המרכז", r"בכיוון החיובי פועלים הכוח הנורמלי והכובד", r"N + mg = m\,\frac{v_D^2}{r}", eq=r"a_R = \frac{v^2}{r}"),
        S(r"התנאי שהגוף לא ייפרד", r"הכוח הנורמלי לא יכול להיות שלילי. המקרה הגבולי הוא כוח נורמלי אפס", r"N \ge 0 \;\Rightarrow\; v_D^2 \ge g\,r"),
        S(r"המהירות בראש הלולאה", r"שימור אנרגיה. הנקודה D גבוהה מ-B בפעמיים הרדיוס הקטן", r"mgR = mg \cdot 2r + \tfrac{1}{2}m v_D^2 \;\Rightarrow\; v_D^2 = 2g(R - 2r)", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
        S(r"מציבים בתנאי", r"מחלקים בתאוצת הכובד וברדיוס הקטן", r"2g(R - 2r) \ge g\,r \;\Rightarrow\; 2R \ge 5r \;\Rightarrow\; \frac{R}{r} \ge \frac{5}{2}"),
    ], r"$R/r = 5/2$", key=r"R/r = 5/2"),
    P("ד", r"הסבירו מדוע הכוח השקול על הגוף, בזמן שהוא נע בקטע שאחרי הנקודה $A$ ועד הנקודה $B$, לא משיק למסילה.", OPEN, ["principle"], [
        S(r"כיוון התנועה משתנה", r"המסלול עקום, ולכן יש תאוצה רדיאלית, ולכוח השקול יש רכיב אל המרכז", r"a_R = \frac{v^2}{R} \ne 0", eq=r"a_R = \frac{v^2}{r}"),
    ], r"כי המסלול עקום, ויש תאוצה רדיאלית (פרט לנקודה $A$, שבה $v = 0$)"),
  ],
  concepts=["מעגל אנכי", "שימור אנרגיה", "תאוצה רדיאלית ומשיקית", "תנאי לא-ניתוק בלולאה"],
  summary=r"גוף שגולש ממסילה מעגלית לתוך לולאה: מהירות ותאוצות בצד הלולאה, והיחס $R/r$ הקטן ביותר כדי לעבור את הלולאה.",
  review="הנחה שלי.\nבמקור סעיף ב הוא (1) ו-(2), וכך גם אצלנו. בסעיפי הביטויים התלמיד בוחר את הביטוי הנכון מתוך ארבעה.\nמה לבדוק: רק לאשר.")
